import os
import re
from html.parser import HTMLParser
from typing import List, Tuple, Union

from deepl import Translator


class _MarkupSplitter(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.parts: List[Tuple[str, str]] = []

    def handle_starttag(self, tag, attrs):
        attrs_str = "".join(
            f' {name}' if value is None else f' {name}="{value}"' for name, value in attrs
        )
        self.parts.append(("tag", f"<{tag}{attrs_str}>"))

    def handle_endtag(self, tag):
        self.parts.append(("tag", f"</{tag}>"))

    def handle_startendtag(self, tag, attrs):
        attrs_str = "".join(
            f' {name}' if value is None else f' {name}="{value}"' for name, value in attrs
        )
        self.parts.append(("tag", f"<{tag}{attrs_str}/>"))

    def handle_data(self, data):
        self.parts.append(("text", data))

    def handle_entityref(self, name):
        self.parts.append(("tag", f"&{name};"))

    def handle_charref(self, name):
        self.parts.append(("tag", f"&#{name};"))

    def handle_comment(self, data):
        self.parts.append(("tag", f"<!--{data}-->"))

    def handle_decl(self, decl):
        self.parts.append(("tag", f"<!{decl}>"))

    def handle_pi(self, data):
        self.parts.append(("tag", f"<?{data}>"))


def translate_markup(text: str, target_lang: str, source_lang: str = None, preserve_tags: bool = True) -> str:
    """
    Translate HTML or markup while preserving tags using DeepL API.

    Environment:
        DEEPL_AUTH_KEY: DeepL API auth key.
    """
    auth_key = os.environ.get("DEEPL_AUTH_KEY")
    if not auth_key:
        raise EnvironmentError("DEEPL_AUTH_KEY is required")

    translator = Translator(auth_key)

    if not preserve_tags:
        result = translator.translate_text(text, target_lang=target_lang, source_lang=source_lang)
        return result.text

    parser = _MarkupSplitter()
    parser.feed(text)
    parser.close()

    translated_parts: List[str] = []
    buffer: List[str] = []

    def flush_buffer():
        if not buffer:
            return
        segment = "".join(buffer)
        buffer.clear()
        if segment.strip():
            result = translator.translate_text(
                segment,
                target_lang=target_lang,
                source_lang=source_lang,
                tag_handling="html",
            )
            translated_parts.append(result.text)
        else:
            translated_parts.append(segment)

    for kind, value in parser.parts:
        if kind == "text":
            buffer.append(value)
        else:
            flush_buffer()
            translated_parts.append(value)

    flush_buffer()
    return "".join(translated_parts)
